                               bit_depth)) {
                    randomize_buffers();
                    ftx(coef, tx, txtp, sz, bit_depth);

                    for (sub = (txtp == 0) ? 1 : 2; sub <= sz; sub <<= 1) {
                        int eob;

                        if (sub < sz) {
